window.LBL_FONT_DATA={
'BL Big Shoulders|800':'',
'BL Bebas Neue|400':'',
'BL Oswald|600':'',
'BL Josefin Sans|600':'',
'BL Comfortaa|700':'',
'BL Public Sans|400':'',
'BL Public Sans|700':'',
'BL Playfair Display|700':'',
'BL Cinzel|700':'',
'BL Abril Fatface|400':'',
'BL Roboto Slab|400':'',
'BL Roboto Slab|700':'',
'BL Alfa Slab One|400':'',
'BL Rye|400':'',
'BL UnifrakturMaguntia|400':'',
'BL Lobster|400':'',
'BL Pacifico|400':'',
'BL Great Vibes|400':'',
'BL IBM Plex Mono|400':'',
};
(function(){
  if(!window.FontFace || !document.fonts) { window.LBL_FONTS_READY=Promise.resolve(); return; }
  var ps=[];
  for(var k in window.LBL_FONT_DATA){
    var p=k.split('|');
    try{ var f=new FontFace(p[0],'url(data:font/woff2;base64,'+window.LBL_FONT_DATA[k]+') format("woff2")',{weight:p[1]});
      document.fonts.add(f); ps.push(f.load().catch(function(){})); }catch(e){}
  }
  window.LBL_FONTS_READY=Promise.all(ps);
})();
